slides.code:
.frm_txt{
    width: 150px;  height: 30px;
    outline: none;  border: 1px solid #ccc;
    padding-left: 8px;  border-radius: 5px;  margin-left: 6px;
}
.frm_radio, .frm_chkbox{ display: none; }
.frm_radio+span, .frm_chkbox+span {
    width: 50px;  height: 30px;
    display: inline-block;
    background-color: #ccc;
    border-radius: 5px;
    font: 16px/30px "微软雅黑";
    text-align: center;
}
.frm_radio:checked+span{ color:#fff; background-color: darkblue; }
.frm_chkbox+span{ background: url("image/unchecked.png") no-repeat;
    background-size: 30px 30px; padding-left: 35px; }
.frm_chkbox:checked+span{ background: url("image/checked.png") no-repeat;
    background-size: 30px 30px; }
.file{ position: relative; display: inline-block; }
.frm_file{ position: absolute; right:0; top:0;
    opacity: 0; width: 100%; height: 100%; }

*{ margin:0px; padding:0px; }
body{ background: #f6f6f6; font:12px/1.5 tahoma,Microsoft YaHei,sans-serif; }
li{ list-style: none; }
a{ text-decoration: none; }
.w{ width: 1080px; margin:0 auto; }
.nav-simple{ height: 60px; line-height: 60px; background-color: #Fff; }
.nav-simple .logo{ font-size: 26px; font-weight: bold; color:#c60023; }
.page-wrap{ background-color: #e72955; padding: 40px 0; }
.user-con{ width: 400px; background-color: #fff; margin:0 auto; }
.user-con .user-title{ text-align: center; font-size: 18px; font-weight: bold;
    color:#666; padding:10px 0px; }
.user-con .user-box{ padding:20px; }
.user-con .user-item{ position: relative; margin-bottom: 20px; }
.user-item .user-label{ position: absolute; left:1px; bottom:1px; width: 40px;
    line-height: 36px; font-size: 18px; color:#d3d3d3; text-align: center;
    border-right:1px solid #bdbdbd; }
.user-item .user-content{ padding:10px 0 10px 50px; width: 308px; height: 18px;
    line-height: 18px; font-size: 15px; border:1px solid #bdbdbd; outline:none; }
.btn{ display: inline-block; height: 40px; line-height: 40px; font-size: 17px;
    font-weight: bold; padding:0 20px; background-color: #c60023; color:#fff; }
.btn-submit{ width: 100%; padding:6px 0px; text-align: center; font-size: 20px; }
.user-con .link-item{ text-align: right; margin-top: 10px; }
.link-item .link{ color:#999; margin-left: 10px; }
